INSERT INTO `genero` (`id`, `descricao`, `nome`, `status_desc`, `uuid`) VALUES (52,'Gênero focado em lutas, combates e confrontos físicos. Protagonistas frequentemente possuem habilidades especiais e enfrentam vilões em batalhas épicas.','Ação','Active','52e4c24f-c30f-47f0-aa63-3bd632dea755'),(53,'Histórias centradas em jornadas, explorações e descobertas. Personagens embarcam em missões perigosas para alcançar objetivos grandiosos.','Aventura','Active','36c2b4ae-b2bf-49bd-be5e-45c3619c21e8'),(54,'Narrativas que giram em torno de artes marciais e estilos de combate tradicionais. Inclui séries sobre karatê, kung fu, judô e lutas livres.','Artes Marciais','Active','1c3fba74-f204-4463-b439-19311ac95098'),(55,'Obras que visam provocar risos e entretenimento leve. Pode variar de comédia romântica a sátira social e humor absurdo.','Comédia','Active','35740651-c0cf-477e-951a-eb4ca386caed'),(56,'Histórias que exploram conflitos emocionais profundos, relacionamentos humanos e situações da vida real com profundidade dramática.','Drama','Active','b88057df-ed39-49d8-ae89-73a16af76ccc'),(57,'Séries ambientadas em escolas, retratando a vida estudantil, amizades, rivaisidades e o crescimento pessoal dos personagens durante a adolescência.','Escola','Active','986e136a-fa42-4893-bcb8-5330860ab0a7'),(58,'Obras que retratam esportes e competições atléticas. Inclui desde futebol e basquete até esportes fictícios e competições sobre-humanas.','Esportes','Active','ecf15ffb-d711-4584-827e-a9b000af5cab'),(59,'Mundos imaginários com elementos mágicos, criaturas fantásticas, dragões, magia e reinos encantados que desafiam as leis da natureza.','Fantasia','Active','eef12ae4-f5db-4f5d-a69b-5489cb676e56'),(60,'Narrativas ambientadas no futuro ou em realidades alternativas, explorando avanços tecnológicos, viagens espaciais e conceitos científicos.','Ficção Científica','Active','3971785f-3729-4c1a-924a-330edfaa1b7e'),(61,'Obras que buscam provocar medo e tensão no espectador. Inclui恐怖, sobrenatural, slasher e terror psicológico.','Horror','Active','49cef232-2db7-4972-a8df-77680fadeaaa'),(62,'Protagonista é transportado ou renasce em um mundo diferente, geralmente fantástico, onde deve sobreviver e prosperar com conhecimentos do mundo original.','Isekai','Active','e82e0d8c-1566-4f80-b13f-7d0b79f14350'),(63,'Séries baseadas em jogos eletrônicos, jogos de mesa ou onde jogos são centrais para a trama. Pode incluir MMORPGs e realidades virtuais.','Jogo','Active','7d84c8ca-3090-4937-9daf-dbcb689c08cd'),(64,'Subgênero do shojo com foco em transformações mágicas, garotas guerreiras e temas de amizade e justiça com elementos sobrenaturais.','Magical Girl','Active','7513d59f-4512-4bc0-aa8f-582e0ccfa38d'),(65,'Robôs gigantes pilotos por humanos, geralmente em contexto de guerra ou defesa contra ameaças. Um dos gêneros mais icônicos do anime.','Mecha','Active','59728290-db1f-47ec-acad-5fdc610e8aa9'),(66,'Histórias centradas em enigmas, investigações e situações que desafiam a compreensão. Requer atenção do espectador para resolver mistérios.','Mistério','Active','df515769-b25d-486d-9a11-509123b83daf'),(67,'Obras que utilizam música como elemento central da trama, seja como profissão dos personagens ou como catalisador de eventos.','Musical','Active','3c950f06-67b0-4d48-b2c8-bb2855f31fa4'),(68,'Narrativas que exploram a psique humana, comportamentos obsessivos, dilemas morais e a natureza da realidade e da percepção.','Psicológico','Active','6bf6a18d-c852-447f-820f-e273412b39c7'),(69,'Histórias focadas em relacionamentos amorosos, desde romances adolescentes até dramas adultos, explorando sentimentos e conexões emocionais.','Romance','Active','7cdfe07a-6ccf-4c12-a30e-aa2c2ef7ed89'),(70,'Ficção científica ocidental com ênfase em exploração espacial, sociedades futuristas e tecnologias avançadas.','Sci-Fi','Active','7fbf79d2-79a4-40ce-b818-9c5a5cdca63d'),(71,'Gênero voltado para público adulto com temas maduros, violência gráfica, suspense complexo e narrativas psicologi